create table if not exists public.courses(id uuid primary key default gen_random_uuid(),title text not null,level text not null,description text,created_at timestamptz not null default now());
create table if not exists public.modules(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,position int not null default 0);
create table if not exists public.lessons(id uuid primary key default gen_random_uuid(),module_id uuid not null references public.modules(id) on delete cascade,title text not null,position int not null default 0,content jsonb not null default '{}'::jsonb);
create table if not exists public.user_progress(user_id uuid not null references public.profiles(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completed boolean not null default false,score numeric,updated_at timestamptz not null default now(),primary key(user_id,lesson_id));
create table if not exists public.user_vocabulary(user_id uuid not null references public.profiles(id) on delete cascade,word text not null,meaning text,example text,interval_days int not null default 1,next_review date not null default current_date,review_count int not null default 0,primary key(user_id,word));
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),code text unique not null,title text not null,description text not null);
create table if not exists public.user_achievements(user_id uuid not null references public.profiles(id) on delete cascade,achievement_id uuid not null references public.achievements(id) on delete cascade,earned_at timestamptz not null default now(),primary key(user_id,achievement_id));
create table if not exists public.conversation_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,topic text not null,level text,created_at timestamptz not null default now());
create table if not exists public.conversation_messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.conversation_sessions(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null,created_at timestamptz not null default now());
create table if not exists public.grammar_corrections(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,session_id uuid references public.conversation_sessions(id) on delete cascade,original_text text not null,corrected_text text not null,explanation text,natural_alternative text,created_at timestamptz not null default now());
create table if not exists public.subscriptions(user_id uuid primary key references public.profiles(id) on delete cascade,status text not null default 'free',provider text,provider_customer_id text,updated_at timestamptz not null default now());
create table if not exists public.ai_usage(user_id uuid not null references public.profiles(id) on delete cascade,usage_date date not null default current_date,requests int not null default 0,seconds int not null default 0,primary key(user_id,usage_date));
alter table public.user_progress enable row level security; alter table public.user_vocabulary enable row level security; alter table public.user_achievements enable row level security; alter table public.conversation_sessions enable row level security; alter table public.conversation_messages enable row level security; alter table public.grammar_corrections enable row level security; alter table public.subscriptions enable row level security; alter table public.ai_usage enable row level security;
create policy "progress own" on public.user_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "vocab own" on public.user_vocabulary for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "achievements own" on public.user_achievements for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "conversation own" on public.conversation_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "messages own" on public.conversation_messages for all using(auth.uid()=(select user_id from public.conversation_sessions s where s.id=session_id)) with check(auth.uid()=(select user_id from public.conversation_sessions s where s.id=session_id));
create policy "grammar own" on public.grammar_corrections for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "subscription own" on public.subscriptions for select using(auth.uid()=user_id);
create policy "usage own" on public.ai_usage for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
